# [ A©t0r © ] SECURE MONOLITH ENGINE
$Locked_Blob = ''
$NodeID = '57BF917347C0B4DC6D4ABD3F6B16405A3D97971ADF7E52FA55CFEA244C289BEA'
$Pass = Read-Host "Введите секретное слово A©tor"
if ($Pass.Length -eq 0) { exit }
$Key = [System.Text.Encoding]::UTF8.GetBytes($Pass)
$Bytes = [Convert]::FromBase64String($Locked_Blob)
$Dec = New-Object Byte[] $Bytes.Length
for($i=0; $i -lt $Bytes.Length; $i++) { $Dec[$i] = $Bytes[$i] -bxor $Key[$i % $Key.Length] }
try {
    $Data = [System.Text.Encoding]::UTF8.GetString($Dec) | ConvertFrom-Json
    Write-Host "[ OK ] Доступ разрешен." -ForegroundColor Green
    foreach ($item in $Data.psobject.properties) {
        [System.IO.File]::WriteAllBytes(".\REGENERATED_$NodeID$(.Name)", [Convert]::FromBase64String($item.Value))
    }
} catch { Write-Host "Ошибка ключа!" -ForegroundColor Red }
